ALTER TABLE public.notifications ADD COLUMN IF NOT EXISTS event_key text;
CREATE UNIQUE INDEX IF NOT EXISTS notification_event_key_unique ON public.notifications(event_key) WHERE event_key IS NOT NULL;
ALTER FUNCTION public.patient_relationship_preparation_guard() SECURITY INVOKER;
CREATE OR REPLACE FUNCTION public.patient_trip_event_notification() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE request_id uuid;patient_ws uuid;reference text;label text; event_stamp text; BEGIN
IF TG_TABLE_NAME='request_status_events' THEN request_id:=NEW.ride_request_id;event_stamp:=NEW.id::text;label:=CASE WHEN NEW.to_state IN ('approved','confirmed','accepted','provider_selected') THEN 'Provider selected or accepted' WHEN NEW.to_state IN ('canceled','cancelled','declined','denied') THEN 'Trip canceled or denied' WHEN NEW.to_state IN ('payment_pending','awaiting_payment','waiting_on_payment') THEN 'Waiting on payment' ELSE 'Request status updated' END;
ELSIF TG_TABLE_NAME='ride_requests' THEN request_id:=NEW.id;event_stamp:='received';label:='Request received';
ELSIF TG_TABLE_NAME='trip_invoice_documents' THEN request_id:=NEW.request_id;event_stamp:=NEW.id::text||':'||NEW.status;IF NEW.status='paid' THEN label:='Payment confirmed';ELSIF NEW.status IN ('ready','sent','payment_pending') THEN label:='Waiting on payment';END IF;
ELSE request_id:=NEW.ride_request_id;event_stamp:=NEW.id::text||':'||coalesce(NEW.updated_at::text,now()::text);label:=CASE WHEN NEW.status='completed' AND NEW.status IS DISTINCT FROM OLD.status THEN 'Trip completed' WHEN NEW.status IN ('canceled','cancelled','denied') AND NEW.status IS DISTINCT FROM OLD.status THEN 'Trip canceled or denied' WHEN NEW.scheduled_start_time IS NOT NULL AND NEW.scheduled_start_time IS DISTINCT FROM OLD.scheduled_start_time THEN 'Added to dispatch schedule' WHEN NEW.driver_id IS DISTINCT FROM OLD.driver_id OR NEW.vehicle_id IS DISTINCT FROM OLD.vehicle_id THEN 'Driver or pickup information updated' WHEN NEW.status IN ('assigned','confirmed','accepted') AND NEW.status IS DISTINCT FROM OLD.status THEN 'Provider selected or accepted' END;END IF;
IF label IS NULL OR request_id IS NULL THEN RETURN NEW;END IF;
SELECT coalesce(r.patient_workspace_id,CASE WHEN w.account_type='private_pay' THEN r.workspace_id END),r.mfn_id INTO patient_ws,reference FROM public.ride_requests r LEFT JOIN public.workspaces w ON w.id=r.workspace_id WHERE r.id=request_id AND NOT r.is_test;
IF patient_ws IS NULL THEN RETURN NEW;END IF;
INSERT INTO public.notifications(user_id,type,title,body,ride_request_id,link,event_key) SELECT m.user_id,'trip_patient_event',label,coalesce(reference,'Trip request'),request_id,'/portal/requests','patient-trip:'||TG_TABLE_NAME||':'||event_stamp||':'||m.user_id FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=patient_ws AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND w.account_type='private_pay' AND w.status='active' AND NOT w.is_test_account AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL ON CONFLICT DO NOTHING;
RETURN NEW;END $$;
CREATE TRIGGER patient_request_received AFTER INSERT ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.patient_trip_event_notification();
CREATE TRIGGER patient_invoice_update AFTER INSERT OR UPDATE OF status ON public.trip_invoice_documents FOR EACH ROW EXECUTE FUNCTION public.patient_trip_event_notification();